import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"Features","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/features.md","filePath":"en/guide/features.md","lastUpdated":1785861127000}'),i={name:"en/guide/features.md"};function s(n,e,d,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h1><p>Every CZero feature can be toggled independently in <code>config.json</code> and runs on its own schedule. This page covers <strong>what each feature does, when it runs, and what safeguards apply</strong>. For field-by-field values, see <a href="/en/guide/configuration">Configuration</a>.</p><h2 id="cache-cleaning" tabindex="-1">Cache cleaning <a class="header-anchor" href="#cache-cleaning" aria-label="Permalink to &quot;Cache cleaning&quot;">​</a></h2><p>Dedicated cleaners for frequently used apps (WeChat, QQ, Douyin), triggered at the frequency of <code>app_clean.detect_schedule</code>.</p><h3 id="checks-before-triggering" tabindex="-1">Checks before triggering <a class="header-anchor" href="#checks-before-triggering" aria-label="Permalink to &quot;Checks before triggering&quot;">​</a></h3><p>Each trigger first examines the app&#39;s current state to avoid pointless or harmful cleaning:</p><ul><li><strong>Never cleans the foreground app</strong> — if an app is currently in use in the foreground, it is skipped this round so ongoing actions aren&#39;t disrupted.</li><li><strong>Game-foreground protection</strong> — cleaning is skipped while a game is in the foreground.</li></ul><h3 id="per-app-switches" tabindex="-1">Per-app switches <a class="header-anchor" href="#per-app-switches" aria-label="Permalink to &quot;Per-app switches&quot;">​</a></h3><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;wechat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;enabled&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;enhanced&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><ul><li><code>enabled</code> — whether to clean this app.</li><li><code>enhanced</code> — <strong>enhanced mode</strong>. Widens the cleaning scope; off by default for safety.</li></ul><h3 id="other-apps-cleaning" tabindex="-1">Other-apps cleaning <a class="header-anchor" href="#other-apps-cleaning" aria-label="Permalink to &quot;Other-apps cleaning&quot;">​</a></h3><p><code>app_clean.other</code> handles caches beyond the big three, run on its <code>schedule</code> (default daily 03:00).</p><h3 id="master-switch-temporal-barrier" tabindex="-1">Master switch &amp; temporal barrier <a class="header-anchor" href="#master-switch-temporal-barrier" aria-label="Permalink to &quot;Master switch &amp; temporal barrier&quot;">​</a></h3><ul><li>Governed by the master switch <code>general.auto_clean</code>.</li><li>Protected by <code>general.temporal_barrier_days</code> (the <strong>temporal barrier</strong>): only files older than N days are cleaned, protecting recent data; <code>0</code> disables it.</li></ul><h2 id="background-suppression" tabindex="-1">Background suppression <a class="header-anchor" href="#background-suppression" aria-label="Permalink to &quot;Background suppression&quot;">​</a></h2><p>At the frequency of <code>suppress.detect_schedule</code>, terminates the target apps&#39; background processes to free memory and reduce background drain.</p><ul><li><strong>Subprocesses only</strong> — the main process is untouched, so notifications and push still work.</li><li><strong>Never touches the foreground app</strong> — an app currently in the foreground is never suppressed, and if the foreground app cannot be determined this round, suppression is skipped entirely.</li><li><strong>Editable list</strong> — WeChat / QQ / Alipay by default; apps can be added, removed, or toggled individually in CZeroX.</li></ul><h2 id="f2fs-garbage-collection" tabindex="-1">F2FS garbage collection <a class="header-anchor" href="#f2fs-garbage-collection" aria-label="Permalink to &quot;F2FS garbage collection&quot;">​</a></h2><p>Runs F2FS garbage collection (GC) when free space gets tight, consolidating fragmented space.</p><p>GC is disk-intensive, so it only acts when the device is genuinely idle. Failing any of the following skips the round:</p><table tabindex="0"><thead><tr><th>Condition</th><th>Field</th><th>Default</th></tr></thead><tbody><tr><td>Storage actually needs reclaiming</td><td><code>free_percent</code> / <code>target_percent</code></td><td>triggers below 95% free, considered done at 98%</td></tr><tr><td>Screen must be off</td><td><code>wait_screen_off_timeout</code></td><td>waits up to 30s, then gives up</td></tr><tr><td>Interval since the last run</td><td><code>min_interval_hours</code></td><td>6 hours</td></tr><tr><td>Must be charging</td><td><code>require_charging</code></td><td>off (not required)</td></tr><tr><td>Minimum battery when not charging</td><td><code>min_battery</code></td><td>40%</td></tr><tr><td>Battery temperature ceiling</td><td><code>max_battery_temp</code></td><td>40.0°C</td></tr></tbody></table><p><code>max_runtime_sec</code> additionally caps a single run and force-stops it when reached.</p><div class="tip custom-block"><p class="custom-block-title">Rarely seeing it run is normal</p><p>The admission conditions are deliberately strict, and CZero yields when the system is already performing its own maintenance. If several runs in a row achieve little, the interval lengthens automatically to avoid pointless retries.</p></div><blockquote><p>GC requires an F2FS <code>/data</code> partition. On non-F2FS devices, set <code>gc.enabled</code> to <code>false</code>; everything else works regardless.</p></blockquote><h2 id="fstrim" tabindex="-1">fstrim <a class="header-anchor" href="#fstrim" aria-label="Permalink to &quot;fstrim&quot;">​</a></h2><p><code>trim</code> is a separate job from GC (weekly at 04:00 by default). It tells the underlying storage which space has been freed, so the UFS / eMMC controller&#39;s own reclamation has something to work with — which keeps write performance healthy over time.</p><ul><li>Scheduled <strong>independently</strong> of GC and unaffected by <code>gc.enabled</code>.</li><li>Also requires the screen to be off; the round is skipped if the screen is on.</li></ul><div class="warning custom-block"><p class="custom-block-title">Don&#39;t run it too often</p><p>fstrim puts real write pressure on the storage device. The weekly default is plenty; daily is not recommended.</p></div><h2 id="fine-grained-suppression" tabindex="-1">Fine-grained suppression <a class="header-anchor" href="#fine-grained-suppression" aria-label="Permalink to &quot;Fine-grained suppression&quot;">​</a></h2><p><a href="#background-suppression">Background suppression</a> above simply terminates background processes. <strong>Fine-grained suppression</strong> is the gentle counterpart — it <strong>suppresses without killing</strong>: a suppressed app stops burning CPU, but its in-memory state is preserved, so switching back to it resumes instantly with nothing to reload.</p><p>The capability comes from Android itself. The module does not perform it — it only brings it into a usable state at boot:</p><table tabindex="0"><thead><tr><th>Field</th><th>What it does</th></tr></thead><tbody><tr><td><code>auto_enable</code></td><td>Enables the system&#39;s fine-grained suppression capability on each boot</td></tr><tr><td><code>disable_vendor_guard</code></td><td>Turns off the vendor&#39;s own keep-alive/suppression stack so the two strategies don&#39;t fight</td></tr></tbody></table><p>The list of apps to suppress is managed in CZeroX, not written into <code>config.json</code>.</p><div class="tip custom-block"><p class="custom-block-title">Which one to use</p><p>They coexist. Background suppression suits subprocesses that are harmless to kill and only waste memory otherwise; fine-grained suppression suits apps whose live state you want preserved but which shouldn&#39;t be active in the background.</p></div><div class="warning custom-block"><p class="custom-block-title">Requires Android 12+</p><p>On older versions these two switches have no effect.</p></div><h2 id="empty-folder-cleanup" tabindex="-1">Empty-folder cleanup <a class="header-anchor" href="#empty-folder-cleanup" aria-label="Permalink to &quot;Empty-folder cleanup&quot;">​</a></h2><p>On the <code>empty_folder.schedule</code> (default daily 04:00), sweeps away leftover empty directories. Both the sweep scope and its whitelist are editable in CZeroX, organized into groups that can be toggled as a whole.</p><h2 id="custom-path-cleaning" tabindex="-1">Custom-path cleaning <a class="header-anchor" href="#custom-path-cleaning" aria-label="Permalink to &quot;Custom-path cleaning&quot;">​</a></h2><p>Beyond the built-in rules, you can declare your own cleaning paths for the daily job, and use a whitelist to protect directories that should never be touched. Both are managed in CZeroX&#39;s rule editor and are inherited across reinstalls.</p><p>Rules support wildcards and are deduplicated automatically (paths beneath a directory already on the list are not processed twice); the whitelist always takes priority.</p><p>Alongside the path-grouped rules there is a second set organized <strong>by app</strong>: the &quot;App cache&quot; page in CZeroX shows the real disk usage of each path per app, lets you add or remove entries, and can pull community-verified rules from the shared cloud library. Both sets are merged at cleaning time and behave identically.</p><p>You can also subscribe to third-party <a href="/en/guide/rule-source">rule sources</a>, which update once a day.</p><p>Cleaning does not delete outright — matched files are first moved to the recycle bin (see below), kept for 7 days by default, and fully recoverable during that window.</p><h2 id="recycle-bin-restore" tabindex="-1">Recycle bin &amp; restore <a class="header-anchor" href="#recycle-bin-restore" aria-label="Permalink to &quot;Recycle bin &amp; restore&quot;">​</a></h2><p>To make accidental deletion recoverable, other / custom-path cleaning <strong>does not truly delete</strong>. Instead it <strong>moves</strong> matched files into a recycle bin, keeping them for a while and only purging them once they expire.</p><ul><li><strong>Move, not delete</strong> — cleaned files retain their original directory structure and can be <strong>restored to their exact original location</strong>, symlinks included.</li><li><strong>Archived per run</strong> — each cleaning run forms its own record, showing which files it removed, how large they were, and when they expire.</li><li><strong>Kept for 7 days by default</strong> — adjustable via <code>general.recycle_keep_days</code> (absent or <code>0</code> means 7). Expired records are purged automatically.</li><li><strong>Hidden from the gallery</strong> — moved photos and videos don&#39;t show up in the media library.</li><li><strong>Preserves mtime</strong> — restored files aren&#39;t misjudged as &quot;new&quot; by the temporal barrier.</li><li><strong>Self-protection</strong> — even if a rule matches the root of internal storage, the recycle bin itself is never cleaned.</li></ul><p>The recycle bin lives in the <code>Recycle</code> folder on internal storage; day to day, browse and restore from CZeroX&#39;s recycle-bin page.</p><h2 id="stats-logging" tabindex="-1">Stats &amp; logging <a class="header-anchor" href="#stats-logging" aria-label="Permalink to &quot;Stats &amp; logging&quot;">​</a></h2><ul><li><strong>Stats</strong> — per-app cleaning counts, suppression counts and freed space are accumulated, with a 90-day daily history that powers CZeroX&#39;s &quot;Cleaning trends&quot; chart. Counters roll over at 00:00 daily, and a device that was off at midnight does not miss it.</li><li><strong>Logging</strong> — with <code>general.log</code> on, all components write to one shared daily log, each line tagged with its source (<code>[定时]</code> <code>[检测]</code> <code>[微信]</code> <code>[压制]</code> <code>[GC]</code> <code>[空文件夹]</code> <code>[自定义]</code> and so on) so you can tell which stage produced it. Only the current day is kept.</li></ul><p>Both are off by default and can be toggled at any time.</p><h2 id="dynamic-island-notifications" tabindex="-1">Dynamic Island notifications <a class="header-anchor" href="#dynamic-island-notifications" aria-label="Permalink to &quot;Dynamic Island notifications&quot;">​</a></h2><p>Cleaning start and finish are reported to CZeroX, which displays progress and results (including the Dynamic Island). Controlled by <code>general.notification</code>.</p>',52)])])}const g=t(i,[["render",s]]);export{u as __pageData,g as default};
